#!/usr/bin/env bash
# One-click installer: downloads the latest Proton Updater from GitHub and installs it.
#   curl -fsSL https://raw.githubusercontent.com/lokinyauv-create/proton-updater/main/get.sh | bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). MIT License.
set -euo pipefail
REPO="lokinyauv-create/proton-updater"
T="$(mktemp -d)"; trap 'rm -rf "$T"' EXIT
echo "Downloading Proton Updater… / Завантажую Оновлювач Proton…"
curl -fsSL "https://codeload.github.com/$REPO/tar.gz/refs/heads/main" | tar -xz -C "$T" --strip-components=1
bash "$T/install.sh"
